//! Safe type wrappers for the Tox C API.
//!
//! This module is split into two halves:
//!
//! * the *foundation* (this file): the three `macro_rules!` definitions, the
//!   extra `Address` crypto helpers and the private `hex` module — all
//!   hand-written;
//! * the *declarations* (`core/generated/types.rs`): the size constants, the
//!   newtype/byte-array/enum macro invocations and the `ToxError` result type
//!   — all generated by apigen.
//!
//! The three `macro_rules!` are defined before `mod generated` so they are in
//! scope where the generated invocations expand.

macro_rules! impl_byte_array_type {
    ($name:ident, $size:expr) => {
        #[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(pub [u8; $size]);

        impl Serialize for $name {
            fn serialize<S>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error>
            where
                S: serde::Serializer,
            {
                serializer.serialize_str(&hex::encode(&self.0))
            }
        }

        impl<'de> Deserialize<'de> for $name {
            fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
            where
                D: serde::Deserializer<'de>,
            {
                let s = String::deserialize(deserializer)?;
                let bytes = hex::decode(&s)
                    .ok_or_else(|| serde::de::Error::custom("Invalid hex string"))?;
                if bytes.len() != $size {
                    return Err(serde::de::Error::custom(format!(
                        "Invalid length for {}: expected {}, got {}",
                        stringify!($name),
                        $size,
                        bytes.len()
                    )));
                }
                let mut arr = [0u8; $size];
                arr.copy_from_slice(&bytes);
                Ok($name(arr))
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}({})", stringify!($name), hex::encode(&self.0))
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}", hex::encode(&self.0))
            }
        }
    };
}

macro_rules! impl_safe_newtype {
    ($name:ident) => {
        #[derive(
            Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize,
        )]
        pub struct $name(pub u32);

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}", self.0)
            }
        }
    };
}

macro_rules! impl_tox_enum {
    ($name:ident, $ffi:path, { $($variant:ident),* $(,)? }) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
        #[allow(non_camel_case_types)]
        pub enum $name {
            $($variant),*
        }

        impl From<$ffi> for $name {
            fn from(e: $ffi) -> Self {
                match e {
                    $(<$ffi>::$variant => $name::$variant),*
                }
            }
        }

        impl From<$name> for $ffi {
            fn from(e: $name) -> Self {
                match e {
                    $($name::$variant => <$ffi>::$variant),*
                }
            }
        }
    };
}

// The declarative half of this module (size constants, the macro
// invocations, `ToxError` and `Result`) is generated by apigen. The three
// `macro_rules!` above are visible to it because they are defined earlier in
// this same module.
#[path = "core/generated/types.rs"]
mod generated;
pub use generated::*;

impl Address {
    pub fn from_public_key(pk: PublicKey, nospam: u32) -> Self {
        let mut arr = [0u8; ADDRESS_SIZE];
        arr[0..PUBLIC_KEY_SIZE].copy_from_slice(&pk.0);
        arr[PUBLIC_KEY_SIZE..PUBLIC_KEY_SIZE + 4].copy_from_slice(&nospam.to_be_bytes());

        let mut checksum = [0u8; 2];
        for i in (0..PUBLIC_KEY_SIZE + 4).step_by(2) {
            checksum[0] ^= arr[i];
            checksum[1] ^= arr[i + 1];
        }

        arr[ADDRESS_SIZE - 2] = checksum[0];
        arr[ADDRESS_SIZE - 1] = checksum[1];
        Address(arr)
    }

    pub fn public_key(&self) -> PublicKey {
        let mut pk = [0u8; PUBLIC_KEY_SIZE];
        pk.copy_from_slice(&self.0[0..PUBLIC_KEY_SIZE]);
        PublicKey(pk)
    }

    pub fn nospam(&self) -> u32 {
        u32::from_be_bytes(
            self.0[PUBLIC_KEY_SIZE..PUBLIC_KEY_SIZE + 4]
                .try_into()
                .unwrap(),
        )
    }

    pub fn checksum(&self) -> u16 {
        u16::from_be_bytes(
            self.0[PUBLIC_KEY_SIZE + 4..ADDRESS_SIZE]
                .try_into()
                .unwrap(),
        )
    }
}

mod hex {
    pub fn encode(bytes: &[u8]) -> String {
        let mut s = String::with_capacity(bytes.len() * 2);
        for &b in bytes {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }

    pub fn decode(s: &str) -> Option<Vec<u8>> {
        if !s.len().is_multiple_of(2) {
            return None;
        }
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).ok())
            .collect()
    }
}
